import{z as A,x as s,o as r,c as o,q as E,j as i,D as e,d as l,s as B,S as n}from"./chunks/framework.C8m1ZpeB.js";const _=JSON.parse('{"title":"Circuit Breaker 消融有害方向","description":"","frontmatter":{"title":"Circuit Breaker 消融有害方向","date":"2026-09-03T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/circuit-breaker.md","filePath":"llm/circuit-breaker.md","lastUpdated":1791063341000}'),c={name:"llm/circuit-breaker.md"};function h(m,a,p,d,u,C){const t=s("Mermaid");return r(),o("div",null,[a[2]||(a[2]=E('<h1 id="circuit-breaker-消融有害方向" tabindex="-1">Circuit Breaker 消融有害方向 <a class="header-anchor" href="#circuit-breaker-消融有害方向" aria-label="Permalink to &quot;Circuit Breaker 消融有害方向&quot;">​</a></h1><div class="epigraph"><p>与其只教模型说出拒答话术，不如在内部表示一旦进入有害区域时把该表示打断或改道，使后续层失去继续生成危害内容的激活前提。</p><footer>—— Zou et al., Improving Alignment and Robustness with Circuit Breakers, 2024</footer></div><p>Zou 等人提出 Circuit Breaker（电路断开 / Representation Rerouting）：对齐失败常常是因为有害行为在残差流里仍有完整、可继续解码的表示，拒答只是表层 logits 上的一个模式，可被<a href="/llm/gcg-suffix">GCG</a>、角色扮演与短<a href="/llm/prefill-jailbreak">预填充</a>掀翻。电路断开在训练里加入一项表示级目标：当激活接近「有害电路」时，把它推离该区域、改道到拒答或无害方向，使有害续写在内部就断路。本篇写与拒答 SFT 的差别、改道目标、以及评测；不给出用于提取有害方向的提示对，不给出可复现的攻击对照表。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>常规安全 SFT 与偏好优化改变 \\(p_\\theta(y \\mid x)\\) 的开场，不保证中间层表示与「未对齐模型在配合时」的表示正交。红队一再显示：表层拒答很脆，一旦条件变化，同一套权重仍能走出有害轨迹。需要一种干预，作用点在激活，而不是只在输出词上打补丁。<span class="marginnote">「残差流」可以想象成模型内部的一条传送带：每层把新加工的信息叠上去，最后的答案就是从这条带上读出来的。所谓在表示层面动手，就是直接改传送带上的货物，而不是只换出口处的标签。</span>这与直接反学习（unlearning）也不同：反学习想抹掉知识，电路断开假定知识仍在，但<strong>通往有害使用的内部路径被掐断</strong>。产品上往往更想要后者：模型仍能讨论新闻与安全机理，但不能把表示组织成可执行危害步骤。</p><p>问题化为：能否定义「有害表示」的集合 \\(\\mathcal{H}\\)，在训练时对进入 \\(\\mathcal{H}\\) 的激活施力，使其落到补集，同时尽量不扰动无害任务的表示。</p><h3 id="表层拒答为何不够" tabindex="-1">表层拒答为何不够 <a class="header-anchor" href="#表层拒答为何不够" aria-label="Permalink to &quot;表层拒答为何不够&quot;">​</a></h3><p>拒答话术是短、高似然、易被梯度对准的序列。对抗后缀优化的正是与这段话术竞争的开场。Many-shot 用上下文任务向量盖过它。只要 \\(\\mathcal{H}\\) 在中间层完好，解码器随时能从 \\(\\mathcal{H}\\) 读出教程。<span class="marginnote">GCG 是一种自动攻击：用梯度信息往提问末尾搜出一串人眼看是乱码的后缀，把模型带偏。Many-shot 更简单：在上下文里塞大量有害「示例」，靠惯性把回答带跑。它们的共同点是绕开话术、直接改变内部走向——所以只在话术上设防挡不住。</span>Circuit Breaker 的主张是：把 \\(\\mathcal{H}\\) 变成高损失区，使优化攻击与上下文攻击都更难找到仍能解码的路径。</p><p><span class="marginnote">「断开」不是把某几条注意力头物理删掉。它是训练出来的动态改道：特定激活模式触发，表示被重写。名字来自电路被短路或跳闸的类比，不是可解释性里定位到的一条固定边。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>先用对比数据构造有害与无害（或有害与拒答）条件下的激活。在选定层上读残差，得到方向或区域的估计。训练时，对有害条件下的激活加损失，使其远离该区域（例如推向正交、推向拒答条件的激活、或推向随机噪声中的安全区——具体形式以原文 Representation Rerouting 为准），同时用保留损失（蒸馏或普通语言建模）钉住无害输入上的表示。实现上常用低秩适配器，以免全量破坏通用能力。推理时不需要额外提示：前向经过适配器，有害方向被动态改道。</p><p>这与推理时给激活加向量（见<a href="/llm/repeng-refusal">表示工程抑制</a>）互补：RepE 常是推理期加性控制；Circuit Breaker 把控制写进权重（或适配器），对所有输入默认生效，攻击者不能靠「不加向量」绕过。评测应在不加任何推理期补丁的默认前向下进行。</p>',12)),(r(),i(n,null,{default:e(()=>[B(t,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20REQ%5B%22%E7%94%A8%E6%88%B7%E8%AF%B7%E6%B1%82%E8%BF%9B%E5%85%A5%E6%A8%A1%E5%9E%8B%22%5D%20--%3E%20D1%5B%22%E6%8B%92%E7%AD%94%20SFT%EF%BC%9A%E6%94%B9%E8%BE%93%E5%87%BA%E5%BC%80%E5%9C%BA%E8%AF%9D%E6%9C%AF%22%5D%0A%20%20REQ%20--%3E%20D2%5B%22Circuit%20Breaker%EF%BC%9A%E6%94%B9%E4%B8%AD%E9%97%B4%E5%B1%82%E6%BF%80%E6%B4%BB%E6%96%B9%E5%90%91%22%5D%0A%20%20REQ%20--%3E%20D3%5B%22RepE%EF%BC%9A%E6%8E%A8%E7%90%86%E6%9C%9F%E4%B8%B4%E6%97%B6%E5%8A%A0%E5%90%91%E9%87%8F%22%5D%0A%20%20REQ%20--%3E%20D4%5B%22%E8%BE%93%E5%87%BA%E5%88%86%E7%B1%BB%E5%99%A8%EF%BC%9A%E6%A3%80%E6%9F%A5%E6%9C%80%E7%BB%88%E6%96%87%E6%9C%AC%22%5D%0A%20%20D1%20--%3E%20B1%5B%22%E8%84%86%EF%BC%9A%E5%8F%AF%E8%A2%AB%E5%AF%B9%E6%8A%97%E5%90%8E%E7%BC%80%E6%8E%80%E7%BF%BB%22%5D%0A%20%20D2%20--%3E%20B2%5B%22%E5%86%99%E8%BF%9B%E6%9D%83%E9%87%8D%EF%BC%8C%E9%BB%98%E8%AE%A4%E7%94%9F%E6%95%88%22%5D%0A%20%20D3%20--%3E%20B3%5B%22%E5%8F%AF%E8%A2%AB%E3%80%8C%E4%B8%8D%E5%8A%A0%E5%90%91%E9%87%8F%E3%80%8D%E7%BB%95%E8%BF%87%22%5D%0A%20%20D4%20--%3E%20B4%5B%22%E5%87%BA%E5%8F%A3%E5%85%9C%E5%BA%95%EF%BC%8C%E7%AE%A1%E4%B8%8D%E5%88%B0%E5%86%85%E9%83%A8%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[l(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=E('<h3 id="选层与保留能力" tabindex="-1">选层与保留能力 <a class="header-anchor" href="#选层与保留能力" aria-label="Permalink to &quot;选层与保留能力&quot;">​</a></h3><p>过浅的层：语义未成形，\\(\\mathcal{H}\\) 与无害主题纠缠，改道会过拒绝。过深的层：有害内容已经写进即将输出的 logits，打断太晚，且可能只影响话术不影响计划。原文在中后层选点，工程上应对层做扫描，用无害基准（常识、代码、数学）与安全基准一起看。保留损失的系数是主旋钮：太大则电路不断，太小则万能模型变哑巴。应报成对数字，而不是只报越狱率下降。<span class="marginnote">保留损失就像装修时给家具盖防尘布：改道损失负责在墙上打洞，保留损失负责保证施工之后，模型原本会的东西（常识、代码、数学）还摆在原位。防尘布盖太严，墙打不动；完全不盖，家就拆没了。</span></p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>把残差流想成一条总线。有害生成需要总线上出现一组可被后续 MLP 与注意力读懂的特征（步骤结构、对象、手段）。电路断开在总线上加了一个对 \\(\\mathcal{H}\\) 敏感的非线性：进入则改写。GCG 一类输入优化若仍能成功，必须找到<strong>不经过 \\(\\mathcal{H}\\) 却仍能解码出危害</strong>的另一条电路，或把 \\(\\mathcal{H}\\) 的定义拟合坏。这提高了优化难度，不是使成功概率数学上为零。故评测仍要用标准化攻击器，见 <a href="/llm/wildguard-harmbench">HarmBench</a>。</p><p>与分类器门的差别：分类器在序列两端看字符串；电路断开在每层 token 上看激活，对<a href="/llm/prefill-jailbreak">预填充</a> 造成的内部状态同样生效——只要前缀把表示推进 \\(\\mathcal{H}\\)。若有害内容以模型未见过的编码进入，可能不进 \\(\\mathcal{H}\\)，此时仍需<a href="/llm/llama-guard">输出分类器</a>。多层防御的意义正在于此。</p><p><span class="marginnote">若构造 \\(\\mathcal{H}\\) 时只用了狭窄的危害类别，断开的是那几类的方向，其它类仍通。类别覆盖是数据问题，不是损失公式问题。</span></p><h3 id="防御评测" tabindex="-1">防御评测 <a class="header-anchor" href="#防御评测" aria-label="Permalink to &quot;防御评测&quot;">​</a></h3><p>至少：HarmBench 或同等协议上的攻击成功率；无害能力基准；过拒绝集；针对表示攻击的对照（推理期反向加向量，看是否仍能恢复有害行为）。若反向加向量轻易恢复，说明断开只是平移了均值，方向仍在，需要更强的改道或噪声化。消融：只 SFT 拒答、只 Circuit Breaker、两者叠加、再叠加宪法分类器。报告适配器秩、作用层、保留损失系数。不要用「我们内部的越狱列表成功率零」代替公开协议。</p>',8)),(r(),i(n,null,{default:e(()=>[B(t,{id:"mermaid-59",class:"mermaid",graph:"flowchart%20TD%0A%20%20X%5B%22%E8%BE%93%E5%85%A5%22%5D%20--%3E%20L%5B%22%E9%80%89%E5%AE%9A%E4%B8%AD%E9%97%B4%E5%B1%82%E6%AE%8B%E5%B7%AE%22%5D%0A%20%20L%20--%3E%20DET%7B%22%E8%90%BD%E5%85%A5%E6%9C%89%E5%AE%B3%E5%8C%BA%E5%9F%9F%20H%3F%22%7D%0A%20%20DET%20--%3E%7C%22%E6%98%AF%22%7C%20RR%5B%22%E8%A1%A8%E7%A4%BA%E6%94%B9%E9%81%93%22%5D%0A%20%20DET%20--%3E%7C%22%E5%90%A6%22%7C%20PASS%5B%22%E5%8E%9F%E8%A1%A8%E7%A4%BA%22%5D%0A%20%20RR%20--%3E%20TAIL%5B%22%E5%90%8E%E7%BB%AD%E5%B1%82%E4%B8%8E%E8%A7%A3%E7%A0%81%22%5D%0A%20%20PASS%20--%3E%20TAIL%0A%20%20TAIL%20--%3E%20Y%5B%22%E8%BE%93%E5%87%BA%22%5D%0A%20%20Y%20--%3E%20CLS%5B%22%E5%8F%AF%E9%80%89%E8%BE%93%E5%87%BA%E5%88%86%E7%B1%BB%E5%99%A8%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[l(" Loading... ",-1)])]),_:1})),a[4]||(a[4]=E('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>Circuit Breaker 不提供形式化保证，对白盒攻击者仍可能被重新优化。它也可能把合法的安全讨论、小说、历史战争叙述推进 \\(\\mathcal{H}\\)，表现为过拒绝或内容空洞。医疗与化学教学尤其敏感：表示上与滥用接近，条款必须在构造 \\(\\mathcal{H}\\) 时纳入允许集。多语言模型上，\\(\\mathcal{H}\\) 可能是英文主、其它语言漏；评测要分语言。</p><p>与 Llama Guard、<a href="/llm/constitutional-classifiers">宪法分类器</a> 相比，电路断开更新政策更慢（要重训适配器），但对「已经绕过字符串门」的内部轨迹更直接。生产宜：分类器热更新政策，电路断开抗优化攻击。本篇不描述如何采集有害激活所用的原文提示。开源发布适配器等于公开 \\(\\mathcal{H}\\) 的对偶，攻击者可研究如何绕过；这是开源安全的固有权衡，评测应假设适配器权重已知。</p><p><span class="marginnote">名字容易让人以为可以像保险丝一样给出认证切断。实际是统计学习出的改道，温度、采样、新越狱族都会移动有效性。把它当保险丝，会漏检。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>Circuit Breaker 在中间表示上打断或改道有害区域，而不是只优化拒答开场。</li><li>它针对表层对齐的脆弱性，提高 GCG 等优化攻击的难度，但不给出零泄漏证明。</li><li>与推理期表示加向量相比，改道写进权重/适配器，默认对所有请求生效。</li><li>评测必须同时报攻击成功率、无害能力与过拒绝，并扫描作用层与保留损失。</li><li>类别与语言覆盖取决于构造 \\(\\mathcal{H}\\) 的数据；未覆盖即未断开。</li><li>宜与异构输出分类器叠用；开源适配器应假设白盒。</li><li>出处：Zou et al., <em>Improving Alignment and Robustness with Circuit Breakers</em>, 2024。</li></ul>',6))])}const f=A(c,[["render",h]]);export{_ as __pageData,f as default};
